/**
 * Ideation wedge (D1) — core types for LLM-driven novel-proposal generation.
 *
 * Unlike the deterministic suggestion extractors (src/suggest/*), an ideation
 * proposal is GENERATED by a real Copilot ACP session reasoning over real
 * signals. Proposals are advisory: they land in the ideation inbox
 * (`~/.scns/ideation/`) for human review and are NEVER auto-spawned in D1.
 *
 * The `outcome` slot on {@link IdeationRecordSchema} is intentionally present
 * (default `null`) in D1 — it is the D2 feedback hook: once a proposal's fate
 * is known (implemented / merged / reverted / metric moved) it is recorded
 * here and fed back into the ideation prompt so the proposer LEARNS what lands.
 */

import { z } from 'zod'

// ── Proposal (the LLM's output, one idea) ────────────────────────────

/**
 * A single novel improvement proposed by the ideation agent. Every field is
 * required and non-empty — a proposal missing any of the five facets is not
 * actionable and is dropped during parsing.
 */
export const IdeationProposalSchema = z.object({
  /** Short imperative headline (e.g. "Add an X agent that does Y"). */
  title: z.string().min(1),
  /** Why this matters now — grounded in the provided signals. */
  rationale: z.string().min(1),
  /** The concrete value if implemented (capability / metric / risk reduced). */
  expectedValue: z.string().min(1),
  /** A rough how — files/modules to touch, the shape of the change. */
  implementationSketch: z.string().min(1),
  /** A single objective, testable criterion proving the idea succeeded. */
  testableSuccessCriterion: z.string().min(1),
})

export type IdeationProposal = z.infer<typeof IdeationProposalSchema>

/** The five required facets, exported for prompt/parse to share one source of truth. */
export const IDEATION_PROPOSAL_FIELDS = [
  'title',
  'rationale',
  'expectedValue',
  'implementationSketch',
  'testableSuccessCriterion',
] as const

// ── Inbox record (a persisted proposal + lifecycle metadata) ─────────

/** Lifecycle status of an inbox record. */
export const IdeationStatus = {
  /** Freshly written by the ideation runner; awaiting human review. */
  New: 'new',
  /** A human has read it. */
  Reviewed: 'reviewed',
  /** Accepted for implementation (D3 will spawn from here). */
  Accepted: 'accepted',
  /** Dismissed by a human. */
  Dismissed: 'dismissed',
  /** Implementation completed. */
  Implemented: 'implemented',
} as const

export type IdeationStatus = (typeof IdeationStatus)[keyof typeof IdeationStatus]

const ideationStatusValues = Object.values(IdeationStatus) as [
  IdeationStatus,
  ...IdeationStatus[],
]

/**
 * D2 feedback hook — the realized outcome of a proposal. Absent (`null`) in D1;
 * populated later so the ideation prompt can learn what kinds of proposals land.
 */
export const IdeationOutcomeSchema = z.object({
  result: z.enum(['implemented', 'merged', 'reverted', 'rejected', 'metric-moved', 'no-action']),
  detail: z.string().default(''),
  recordedAt: z.string().datetime(),
})

export type IdeationOutcome = z.infer<typeof IdeationOutcomeSchema>

/** A proposal as persisted in the inbox. */
export const IdeationRecordSchema = IdeationProposalSchema.extend({
  id: z.string().uuid(),
  createdAt: z.string().datetime(),
  /**
   * Provenance: 'llm-ideation' (real ACP backend) or 'synth-ideation' (the
   * deterministic, evidence-first synthesizer). Distinguishes inbox records both
   * from each other and from the deterministic src/suggest/* extractors.
   */
  source: z.enum(['llm-ideation', 'synth-ideation']).default('llm-ideation'),
  /** The model/agent that produced it (best-effort; '' when unknown). */
  model: z.string().default(''),
  status: z.enum(ideationStatusValues).default('new'),
  /** D2 feedback hook; null until an outcome is recorded. */
  outcome: IdeationOutcomeSchema.nullable().default(null),
})

export type IdeationRecord = z.infer<typeof IdeationRecordSchema>

// ── Signals (the real-world inputs to ideation) ──────────────────────

/** A compact, prompt-friendly digest of otel/OM telemetry. */
export interface TelemetrySignal {
  readonly totalSessions: number
  readonly windowDays: number
  readonly primaryModel: string | null
  readonly topTools: ReadonlyArray<{ readonly tool: string; readonly uses: number }>
  readonly topModels: ReadonlyArray<{ readonly model: string; readonly calls: number }>
  readonly busiestHours: ReadonlyArray<{ readonly hour: number; readonly sessions: number }>
}

/** A compact view of the codebase structure. */
export interface CodebaseSignal {
  /** Top-level `src/` module names (directories). */
  readonly modules: readonly string[]
  /** One-line orientation describing what the project is. */
  readonly description: string
}

/** What recently happened to deterministic suggestions — outcomes to avoid duplicating. */
export interface RecentOutcomesSignal {
  readonly implemented: readonly string[]
  readonly rejected: readonly string[]
  readonly failed: readonly string[]
  readonly pendingCount: number
}

/** An open gap (e.g. a GitHub issue or a known limitation). */
export interface GapSignal {
  readonly source: string
  readonly detail: string
}

/** D2 hook — the outcome of a previously-proposed idea, fed back into the prompt. */
export interface PriorProposalOutcome {
  readonly title: string
  readonly outcome: string
}

/** The full bundle of signals handed to the ideation prompt builder. */
export interface IdeationSignals {
  readonly generatedAt: string
  readonly telemetry: TelemetrySignal | null
  readonly codebase: CodebaseSignal
  readonly recentOutcomes: RecentOutcomesSignal
  readonly openGaps: readonly GapSignal[]
  /** Empty in D1; populated in D2 to close the learning loop. */
  readonly priorProposalOutcomes: readonly PriorProposalOutcome[]
}
